#!/usr/bin/env python3
"""Audit native-160 and adapted-16 Brain-JEPA checkpoint loading."""

import json
import sys
from pathlib import Path


ROOT = Path(__file__).resolve().parents[1]
sys.path.insert(0, str(ROOT))

from lib.brain_jepa_adapter import CHECKPOINT, create_encoder


def main():
    output_dir = ROOT / "outputs/checkpoint_audit"
    output_dir.mkdir(parents=True, exist_ok=True)
    rows = []
    conditions = [
        (160, "checkpoint"),
        (16, "native"),
        (16, "temporal_mean"),
        (16, "temporal_center"),
    ]
    for num_frames, policy in conditions:
        _, audit = create_encoder(
            init="pretrained",
            num_frames=num_frames,
            position_policy=policy,
            device="cpu",
        )
        audit["num_frames"] = num_frames
        rows.append(audit)
        print(
            f"T={num_frames:3d} policy={policy:15s} "
            f"patch={audit['model_patch_shape']} position={audit['model_position_shape']}"
        )
    payload = {
        "checkpoint": str(CHECKPOINT),
        "conditions": rows,
        "conclusion_guardrail": (
            "The 16-TR adapter changes the temporal token grid from 10 patches to one. "
            "It does not interpolate patch-embedding weights. Native uses the fixed "
            "one-patch sin/cos code generated by the target-grid model."
        ),
    }
    with open(output_dir / "checkpoint_audit.json", "w", encoding="utf-8") as handle:
        json.dump(payload, handle, indent=2)
    print(f"Saved: {output_dir / 'checkpoint_audit.json'}")


if __name__ == "__main__":
    main()
